export type VisualRequest = {
  kind: "images" | "video";
  prompt: string;
  ratio: string;
  style: string;
  count: number;
  strength: number;
  signal: AbortSignal;
  fail?: boolean;
  delay?: number;
};
export const originalArtNames = editorialAssets.map((asset) => asset.id);

export type PreparedDemoVisual = {
  src: string;
  prompt: string;
  kind: "images" | "video";
  ratio: string;
  source: "prepared-local";
  assetId?: string;
  width?: number;
  height?: number;
};

/** Select existing GPT Image 2.5 collection assets; preserve the saved brief. */
export async function prepareDemoVisuals(
  request: VisualRequest,
): Promise<PreparedDemoVisual[]> {
  const { signal, delay = 1100 } = request;
  await new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(new DOMException("Aborted", "AbortError"));
      return;
    }
    const cancel = () => {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", cancel);
      resolve();
    }, delay);
    signal.addEventListener("abort", cancel, { once: true });
  });
  if (request.fail) throw new Error("Simulated local preview failure.");
  const hash =
    [...(request.prompt + request.style)].reduce(
      (sum, char) => sum + char.charCodeAt(0),
      0,
    ) + request.strength;
  return Array.from(
    {
      length:
        request.kind === "video"
          ? 1
          : Math.max(1, Math.min(4, Math.round(request.count))),
    },
    (_, index): PreparedDemoVisual => {
      const asset =
        editorialAssets[
          (Math.abs(Math.trunc(hash) || 0) + index) % editorialAssets.length
        ];
      return {
        src:
          request.kind === "video" ? "/assets/aureform-motion.webm" : asset.src,
        prompt: request.prompt.trim(),
        kind: request.kind,
        ratio: request.ratio,
        source: "prepared-local",
        ...(request.kind === "images"
          ? { assetId: asset.id, width: asset.width, height: asset.height }
          : {}),
      };
    },
  );
}

"use client";
import { useState, useEffect, useCallback, useRef } from "react";
/**
 * A replaceable browser demo adapter. No server/auth/payments are implied.
 * State begins from the same seed on server and client to avoid hydration mismatch.
 */
export function useDemoStore<T>(key: string, seed: T) {
  const initial = useRef(seed);
  const [value, setValue] = useState<T>(seed);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let data = initial.current;
    try {
      const stored = localStorage.getItem(`aureform:${key}`);
      if (stored) data = JSON.parse(stored) as T;
    } catch {}
    setValue(data);
    setReady(true);
  }, [key]);
  const update = useCallback(
    (next: T | ((previous: T) => T)) => {
      setValue((previous) => {
        const result =
          typeof next === "function" ? (next as (p: T) => T)(previous) : next;
        try {
          localStorage.setItem(`aureform:${key}`, JSON.stringify(result));
        } catch {}
        return result;
      });
    },
    [key],
  );
  const reset = useCallback(() => update(initial.current), [update]);
  return [value, update, { ready, reset }] as const;
}

"use client";
import { useLocale, useTranslations } from "next-intl";
import { useCallback } from "react";
import type { Locale } from "@/i18n/messages";
export function useLanguage() {
  const locale = useLocale() as Locale;
  const common = useTranslations("common");
  const l = useCallback(
    (en: string, es: string) => (locale === "es" ? es : en),
    [locale],
  );
  const number = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) =>
      new Intl.NumberFormat(
        locale === "es" ? "es-CO" : "en-US",
        options,
      ).format(value),
    [locale],
  );
  const currency = useCallback(
    (value: number) =>
      number(value, {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0,
      }),
    [number],
  );
  const date = useCallback(
    (value: Date | string, options?: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(
        locale === "es" ? "es-CO" : "en-US",
        options ?? { month: "short", day: "numeric", year: "numeric" },
      ).format(
        new Date(
          typeof value === "string" && value.length === 10
            ? `${value}T12:00:00`
            : value,
        ),
      ),
    [locale],
  );
  return { locale, common, l, number, currency, date };
}

import { publicPath } from "@/lib/public-path";

export type GeneratedImageDownload = {
  src: string;
  filename: string;
  expectedBytes?: number;
};

/**
 * Read the raster from its self-contained, UTF-8 SVG container. Source installs
 * only need that SVG; a binary WebP sibling is not required in the registry.
 */
export async function generatedImageBlob(
  src: string,
  expectedBytes?: number,
): Promise<Blob> {
  const response = await fetch(publicPath(src));
  if (!response.ok) throw new Error("Generated image container unavailable");
  const svg = new DOMParser().parseFromString(
    await response.text(),
    "image/svg+xml",
  );
  if (
    svg.querySelector("parsererror") ||
    svg.documentElement.localName !== "svg" ||
    svg.documentElement.namespaceURI !== "http://www.w3.org/2000/svg"
  ) {
    throw new Error("Invalid generated image container");
  }
  const images = svg.getElementsByTagNameNS(
    "http://www.w3.org/2000/svg",
    "image",
  );
  if (images.length !== 1) throw new Error("Expected one embedded image");
  const href =
    images[0].getAttribute("href") ??
    images[0].getAttributeNS("http://www.w3.org/1999/xlink", "href");
  const match = href?.match(/^data:image\/webp;base64,([A-Za-z0-9+/=\s]+)$/);
  if (!match) throw new Error("Expected an embedded WebP image");
  const encoded = match[1].replace(/\s/g, "");
  if (encoded.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)) {
    throw new Error("Invalid embedded image encoding");
  }
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  if (
    binary.length < 12 ||
    binary.slice(0, 4) !== "RIFF" ||
    binary.slice(8, 12) !== "WEBP" ||
    (expectedBytes !== undefined && bytes.byteLength !== expectedBytes)
  ) {
    throw new Error("Embedded image does not match its WebP metadata");
  }
  return new Blob([bytes], { type: "image/webp" });
}

export async function downloadGeneratedImage({
  src,
  filename,
  expectedBytes,
}: GeneratedImageDownload): Promise<{
  name: string;
  type: string;
  size: number;
}> {
  if (!filename.endsWith(".webp") || /[/\\]/.test(filename)) {
    throw new Error("Expected a WebP filename");
  }
  const blob = await generatedImageBlob(src, expectedBytes);
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  try {
    document.body.append(anchor);
    anchor.click();
  } finally {
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  return { name: filename, type: blob.type, size: blob.size };
}

/**
 * Add the build's mount point to a public asset or native HTML link.
 * Keep next/link and Next's router paths unprefixed: Next handles those itself.
 */
export function publicPath(
  path: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "",
): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const prefix = basePath.trim().replace(/^\/+|\/+$/g, "");
  if (!prefix) return path;
  const base = `/${prefix}`;
  if (
    path === base ||
    path.startsWith(`${base}/`) ||
    path.startsWith(`${base}?`) ||
    path.startsWith(`${base}#`)
  ) {
    return path;
  }
  return `${base}${path}`;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .af-gradient-border {
    border-color: color-mix(in srgb, var(--primary) 40%, var(--border));
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary) 18%, transparent);
  }

  .af-card {
    --tw-shadow: var(--af-card-shadow, var(--af-shadow-soft));
    background-color: var(--af-card-background, var(--surface));
    background-image: var(--af-card-image, none);
    -webkit-backdrop-filter: var(--af-card-blur, none);
    backdrop-filter: var(--af-card-blur, none);
    border-radius: var(--af-radius, 16px);
    transition:
      border-color var(--af-motion-hover) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      background-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-card-flat {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: 0 0 #0000;
    --af-card-blur: none;
  }
  .af-card-elevated {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
  }
  .af-card-glass {
    --af-card-background: var(--af-glass-background);
    --af-card-image: linear-gradient(130deg, color-mix(in srgb, var(--primary) 8%, transparent), transparent 65%);
    --af-card-shadow: var(--af-shadow-soft);
    --af-card-blur: blur(var(--af-glass-blur));
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .af-card-gradient {
    --af-card-background: var(--surface);
    --af-card-image: linear-gradient(135deg, var(--surface) 25%, color-mix(in srgb, var(--af-color-primary) 20%, var(--surface)));
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }

  .af-control-solid { background-image: none; }
  .af-control-gradient {
    background-color: var(--primary);
    background-image: var(--af-gradient-primary);
    color: var(--primary-foreground);
    --tw-shadow: var(--af-shadow-soft);
  }
  .af-control-gradient:hover:not(:disabled,[data-disabled]) {
    --tw-shadow: var(--af-glow);
  }
  .af-control-soft {
    background-color: var(--accent);
    background-image: none;
    color: var(--accent-foreground);
    border: 1px solid color-mix(in srgb, var(--primary) 24%, var(--border));
  }
  .af-control-outline {
    background-color: var(--surface);
    background-image: none;
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
    --tw-shadow: 0 0 #0000;
  }
  .af-control-glass {
    background-color: var(--af-glass-background);
    background-image: linear-gradient(120deg, color-mix(in srgb, var(--primary) 10%, transparent), transparent);
    backdrop-filter: blur(var(--af-glass-blur));
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
  }

  .af-badge-solid, .af-badge-gradient {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  .af-badge-gradient { background-image: var(--af-gradient-primary); }
  .af-badge-soft { background-color: var(--accent); color: var(--accent-foreground); }
  .af-badge-outline { background-color: transparent; color: var(--foreground); border: 1px solid var(--border); }
  .af-badge-glass { background-color: var(--af-glass-background); color: var(--foreground); border: 1px solid var(--border); backdrop-filter: blur(12px); }

  .af-button-destructive[data-appearance] {
    color: var(--destructive-foreground);
    background-color: var(--destructive);
    background-image: none;
    border-color: color-mix(in srgb, var(--destructive-foreground) 45%, var(--border));
  }
  .af-button[data-disabled], .af-button:disabled {
    background-image: none;
    backdrop-filter: none;
  }

  .af-input, .af-textarea {
    border-color: color-mix(in srgb, var(--muted-foreground) 48%, var(--surface));
  }
}

[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card),
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::before,
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .af-button,
  .af-button::before,
  .af-button::after,
  .af-button[aria-busy="true"] > svg,
  .af-hover-card,
  .af-hover-card::before,
  .af-hover-card::after,
  .af-hover-link,
  .af-hover-link::before,
  .af-hover-link::after {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    translate: none !important;
  }
}
